+  const f = fixture(t, true);
+  let release!: () => void;
+  f.layoutGate = new Promise<void>(resolve => { release = resolve; });
+  let entryPrepared = false;
+  const pending = prepareProductionQaFixture(t, { root, home }, async () => { entryPrepared = true; });
